package com.politeness.ading.conductor.controller.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

/**
 * Register an attachment to upload. attachmentId is generated by the client: retries on network jitter and offline replay with the same ID do not register twice.
 */
public record AttachmentCreateRequest(
        @NotBlank @Size(max = 64) String attachmentId,
        @NotBlank @Size(max = 255) String name,
        @Size(max = 128) String mimeType,
        @NotNull @PositiveOrZero Long size) {
}
